from decimal import Decimal, ROUND_HALF_EVEN

STAGE_PROBS = {
    "lead": Decimal("0.05"),
    "qualified": Decimal("0.20"),
    "demo": Decimal("0.40"),
    "proposal": Decimal("0.65"),
    "verbal": Decimal("0.90"),
}

CENT = Decimal("0.01")


def prob_of(stage):
    if stage not in STAGE_PROBS:
        raise ValueError(f"unknown stage {stage!r}; valid stages: {', '.join(sorted(STAGE_PROBS))}")
    return STAGE_PROBS[stage]


def monthly_ev(pipeline):
    """pipeline: iterable of (amount_cents, stage, close_month). Returns {month: Decimal EV} to the cent."""
    totals = {}
    for amount_cents, stage, month in pipeline:
        totals[month] = totals.get(month, Decimal(0)) + Decimal(amount_cents) * prob_of(stage)
    return {m: v.quantize(CENT, rounding=ROUND_HALF_EVEN) for m, v in totals.items()}


def forecast(pipeline):
    """Returns {'unweighted': sum of amounts, 'weighted': sum of EVs, 'monthly': {...}}, all Decimal cents."""
    unweighted = sum((Decimal(a) for a, _, _ in pipeline), Decimal(0))
    monthly = monthly_ev(pipeline)
    weighted = sum(monthly.values(), Decimal(0)).quantize(CENT, rounding=ROUND_HALF_EVEN)
    return {"unweighted": unweighted, "weighted": weighted, "monthly": monthly}

